using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class RebirthCamperCandidateReview{
const string Prefab="Assets/REBIRTHPickupRearCornerCandidate_20261021_v1/rebirthCamper80s.prefab";
const string Output="E:/_Haven/shared/REBIRTHStaged/CamperCorrections_20261021/CandidateReview";
static void Render(string name,Vector3 position,Vector3 target,float size){var cam=new GameObject("Review camera").AddComponent<Camera>();cam.transform.position=position;cam.transform.LookAt(target);cam.orthographic=true;cam.orthographicSize=size;cam.nearClipPlane=.01f;cam.farClipPlane=30;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.14f,.17f,.18f);var rt=new RenderTexture(1500,1100,24){antiAliasing=4};cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes(Output+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=old;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(cam.gameObject);}
public static void Views(string stage){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Directory.CreateDirectory(Output);var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab));foreach(var t in root.GetComponentsInChildren<Transform>(true)){if(t.name=="REBIRTHCamperBodyModule"||t.name.StartsWith("REBIRTHMod"))t.gameObject.SetActive(true);if(new[]{"REBIRTHCampRoofStations","REBIRTHCampInteriorStations","REBIRTHCampPowerEquipment","REBIRTHCampStairVisuals","REBIRTHCampWalkInColliders","REBIRTHPickupOnlyPaint","REBIRTHPickupOnlyBodywork"}.Contains(t.name))t.gameObject.SetActive(false);}RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.6f,.6f,.6f);foreach(var vector in new[]{new Vector3(45,-40,0),new Vector3(25,130,0)}){var l=new GameObject("Review sun").AddComponent<Light>();l.type=LightType.Directional;l.intensity=.8f;l.transform.rotation=Quaternion.Euler(vector);}Render(stage+"-rear-ladder",new Vector3(2,2.6f,-4.8f),new Vector3(.78f,1.9f,-3.40f),.60f);Render(stage+"-front-ladder",new Vector3(-2.4f,2.2f,1.6f),new Vector3(-.93f,1.8f,.45f),.65f);Render(stage+"-truck-metal",new Vector3(-5,3,5),new Vector3(0,1.4f,-.4f),2.7f);Object.DestroyImmediate(root);}
public static void PreviewBrown(){RebirthCamperBrownMetalMatch.Run();Views("brown-metal-preview");RebirthCamperWheelBundleCompare.Run();Debug.Log("BROWN_PREVIEW_AND_WHEEL_COMPARE_COMPLETE");}
